"import { PrismaClient } from "@prisma/client";
import { PrismaMariaDb } from "@prisma/adapter-mariadb";

let prisma: PrismaClient;

if (process.env.NODE_ENV === "production") {
  // Na Vercel/Produção, se a URL for Postgres, instanciamos o Prisma Client padrão.
  // Caso contrário, mantemos MariaDB para testes remotos de homologação.
  const isPostgres = process.env.DATABASE_URL?.startsWith("postgres") || process.env.DATABASE_URL?.startsWith("postgresql");
  if (isPostgres) {
    prisma = new PrismaClient();
  } else {
    const mariadb = require("mariadb");
    const pool = mariadb.createPool({
      host: process.env.DB_HOST || "127.0.0.1",
      port: Number(process.env.DB_PORT) || 3307,
      user: process.env.DB_USER || "root",
      password: process.env.DB_PASSWORD || "",
      database: process.env.DB_NAME || "financas",
      connectionLimit: 10,
    });
    const adapter = new PrismaMariaDb(pool);
    prisma = new PrismaClient({ adapter });
  }
} else {
  // Em desenvolvimento, evitamos conexões duplicadas usando a variável global
  const globalWithPrisma = global as typeof globalThis & {
    prisma?: PrismaClient;
  };
  if (!globalWithPrisma.prisma) {
    const mariadb = require("mariadb");
    const pool = mariadb.createPool({
      host: "127.0.0.1",
      port: 3307,
      user: "root",
      password: "",
      database: "financas",
      connectionLimit: 10,
    });
    const adapter = new PrismaMariaDb(pool);
    globalWithPrisma.prisma = new PrismaClient({ adapter });
  }
  prisma = globalWithPrisma.prisma;
}

export { prisma };
"

"@import "tailwindcss";

:root {
  --background: #f8fafc;
  --foreground: #0f172a;

  --primary: #064e3b;
  --primary-foreground: #ffffff;

  --card: #ffffff;
  --card-foreground: #0f172a;

  --muted: #f1f5f9;
  --muted-foreground: #64748b;

  --border: #e2e8f0;

  --success: #10b981;
  --success-foreground: #ffffff;

  --warning: #f59e0b;
  --warning-foreground: #ffffff;

  --destructive: #ef4444;
  --destructive-foreground: #ffffff;

  --font-geist-sans: var(--font-geist-sans), Inter, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: #0b130e;
    --foreground: #f8fafc;

    --primary: #10b981;
    --primary-foreground: #064e3b;

    --card: #13221b;
    --card-foreground: #f8fafc;

    --muted: #1e3a2b;
    --muted-foreground: #94a3b8;

    --border: #234333;
  }
}

body {
  background-color: var(--background);
  color: var(--foreground);
  font-family: var(--font-geist-sans);
  min-height: 100vh;
}

/* Custom premium scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--muted-foreground);
}

/* Base utility cards */
.premium-card {
  background-color: var(--card);
  color: var(--card-foreground);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.05), 0 2px 4px -2px rgb(0 0 0 / 0.05);
  transition: all 0.2s ease-in-out;
}

.premium-card:hover {
  box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.08), 0 4px 6px -4px rgb(0 0 0 / 0.08);
  transform: translateY(-2px);
}
