""use server";

import { prisma } from "@/lib/db";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

// Quitar Empréstimo por Completo
export async function payLoan(id: string) {
  const hoje = new Date();

  await prisma.$transaction([
    // Atualizar empréstimo para quitado
    prisma.emprestimo.update({
      where: { id },
      data: { status: "quitado" },
    }),
    // Atualizar todas as parcelas em aberto para pagas
    prisma.parcela.updateMany({
      where: { emprestimo_id: id, status: "aberto" },
      data: {
        status: "pago",
        data_pagamento: hoje,
      },
    }),
  ]);

  revalidatePath(`/emprestimos/${id}`);
  revalidatePath("/emprestimos");
  revalidatePath("/clientes");
  return { success: true };
}

// Pagar uma Parcela Individual
export async function payInstallment(id: string, emprestimoId: string) {
  const hoje = new Date();

  // Buscar a parcela
  const parcela = await prisma.parcela.findUnique({
    where: { id },
  });

  if (!parcela) throw new Error("Parcela não encontrada");

  await prisma.parcela.update({
    where: { id },
    data: {
      status: "pago",
      data_pagamento: hoje,
      valor_pago: parcela.valor,
    },
  });

  // Verificar se todas as parcelas do empréstimo foram pagas
  const todasParcelas = await prisma.parcela.findMany({
    where: { emprestimo_id: emprestimoId },
  });

  const todasPagas = todasParcelas.every((p) => p.status === "pago");

  if (todasPagas) {
    await prisma.emprestimo.update({
      where: { id: emprestimoId },
      data: { status: "quitado" },
    });
  }

  revalidatePath(`/emprestimos/${emprestimoId}`);
  revalidatePath("/emprestimos");
  revalidatePath("/clientes");
  return { success: true };
}

