"interface ClientCobrancasViewProps {
  atrasados: Parcela[];
  hojeLista: Parcela[];
  aVencer: Parcela[];
}

type TabType = "atrasados" | "hoje" | "aVencer";

export default function ClientCobrancasView({ atrasados, hojeLista, aVencer }: ClientCobrancasViewProps) {
  const [activeTab, setActiveTab] = useState<TabType>("atrasados");
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isPending, startTransition] = useTransition();

  // Estados de Simulação
  const [showSimulate, setShowSimulate] = useState(false);
  const [simulateProgress, setSimulateProgress] = useState(0);
  const [simulateLogs, setSimulateLogs] = useState<string[]>([]);
  const [isSimulating, setIsSimulating] = useState(false);

  const getActiveList = (): Parcela[] => {
    if (activeTab === "atrasados") return atrasados;
    if (activeTab === "hoje") return hojeLista;
    return aVencer;
  };

  const currentList = getActiveList();

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      setSelectedIds(currentList.map((p) => p.id));
    } else {
      setSelectedIds([]);
    }
  };

  const handleSelectOne = (id: string, checked: boolean) => {
    if (checked) {
      setSelectedIds((prev) => [...prev, id]);
    } else {
      setSelectedIds((prev) => prev.filter((item) => item !== id));
    }
  };

  const formatBRL = (val: number) => {
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency: "BRL",
    }).format(val);
  };

  const formatData = (dateStr: string) => {
    return new Intl.DateTimeFormat("pt-BR", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
      timeZone: "UTC",
    }).format(new Date(dateStr));
  };"

