"  // Obter data atual em UTC
  const hoje = new Date();
  const hojeUTC = new Date(Date.UTC(hoje.getFullYear(), hoje.getMonth(), hoje.getDate()));

  const limite7DiasUTC = new Date(hojeUTC);
  limite7DiasUTC.setUTCDate(hojeUTC.getUTCDate() + 7);

  // Buscar todos os empréstimos ativos com dados do cliente
  const emprestimosAtivos = await prisma.emprestimo.findMany({
    where: {
      status: "ativo",
    },
    include: {
      cliente: true,
    },
    orderBy: {
      data_vencimento: "asc",
    },
  });

  // Calcular métricas
  let totalEmprestado = 0;
  let totalAReceber = 0;
  let totalAtrasadosCount = 0;
  let vencendo7DiasCount = 0;

  const proximosVencimentos = emprestimosAtivos.map((emp) => {
    const principal = Number(emp.valor_emprestado);
    const juros = Number(emp.taxa_juros);
    const totalDevido = principal * (1 + juros / 100);

    totalEmprestado += principal;
    totalAReceber += totalDevido;

    const vencObj = new Date(emp.data_vencimento);
    const vencimentoUTC = new Date(Date.UTC(vencObj.getUTCFullYear(), vencObj.getUTCMonth(), vencObj.getUTCDate()));

    const estaAtrasado = vencimentoUTC < hojeUTC;
    const venceProximos7Dias = vencimentoUTC >= hojeUTC && vencimentoUTC <= limite7DiasUTC;

    if (estaAtrasado) totalAtrasadosCount++;
    if (venceProximos7Dias) vencendo7DiasCount++;

    // Calcular diferença de dias para atraso
    let diasAtraso = 0;
    if (estaAtrasado) {
      const diffTime = Math.abs(hojeUTC.getTime() - vencimentoUTC.getTime());
      diasAtraso = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    }

    return {
      ...emp,
      valorDevidoCalculado: totalDevido,
      estaAtrasado,
      venceProximos7Dias,
      diasAtraso,
    };
  });"

