    totalEmprestado += principal;
    totalAReceber += totalDevido;

    const vencimento = new Date(emp.data_vencimento);
    vencimento.setHours(0, 0, 0, 0);

    const estaAtrasado = vencimento < hoje;
    const venceProximos7Dias = vencimento >= hoje && vencimento <= limite7Dias;

    if (estaAtrasado) totalAtrasadosCount++;
    if (venceProximos7Dias) vencendo7DiasCount++;

    // Calcular diferença de dias para atraso
    let diasAtraso = 0;
    if (estaAtrasado) {
      const diffTime = Math.abs(hoje.getTime() - vencimento.getTime());
      diasAtraso = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    }

    return {
      ...emp,
      valorDevidoCalculado: totalDevido,
      estaAtrasado,
      venceProximos7Dias,
      diasAtraso,
    };
  });"

